files.content:
---
import Button from "@/components/fundations/buttons/Button.astro";
import Text from "@/components/fundations/typography/Text.astro";
import { Image } from "astro:assets";
import g1 from "@/images/gallery/1.png";
import g2 from "@/images/gallery/2.png";
import g3 from "@/images/gallery/3.png";
import g4 from "@/images/gallery/4.png";
---

<section class="bg-background">
  <div class="px-8 py-24 mx-auto max-w-7xl md:px-12 lg:px-20">
    <div class="sm:flex sm:items-center sm:justify-between">
      <div>
        <Text
          variant="textBase"
          class="font-semibold tracking-tight text-foreground"
        >
          Oxbow UI
        </Text>
        <Text
          variant="textSM"
          tag="p"
          class="font-medium text-muted-foreground"
        >
          30 images
        </Text>
      </div>
      <Button variant="default" size="sm"> See gallery </Button>
    </div>

    <div class="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-4">
      <Image
        width={600}
        height={600}
        src={g1}
        alt="#_"
        class="object-cover size-full aspect-square"
      />
      <div class="grid grid-cols-1 gap-4 lg:grid-cols-2">
        <Image
          width={600}
          height={600}
          src={g2}
          alt="#_"
          class="object-cover size-full aspect-square"
        />
        <Image
          width={600}
          height={600}
          src={g3}
          alt="#_"
          class="object-cover size-full aspect-square"
        />
        <Image
          width={600}
          height={600}
          src={g4}
          alt="#_"
          class="object-cover size-full lg:col-span-2"
        />
      </div>
    </div>
  </div>
</section>
